constexpr std::identity pass{};    // <functional>, C++20

// Projection slot: pass{} is already the default projection here.
std::ranges::sort(v, std::less{}, pass);           // == std::ranges::sort(v);

// Neutral element: an empty transform chain reduces to identity
std::function<int(std::string)> make_pipeline(std::vector<Step> steps) {
    std::function<int(std::string)> f = pass;      // base case: no-op transform
    for (auto it = steps.rbegin(); it != steps.rend(); ++it)
        f = [it, f](std::string s) { return f((*it)(std::move(s))); };
    return f;
}

